import { useState } from 'react';
import { JxTable, JxBadge, JxPagination, JxEmptyState } from '@jinx-ui/react';

export interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

export interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);

  if (users.length === 0) {
    return (
      <JxEmptyState
        title="Пользователей пока нет"
        message="Добавьте первого пользователя, чтобы он появился в этом списке."
      />
    );
  }

  const pageCount = Math.ceil(users.length / PAGE_SIZE);
  const currentPage = Math.min(page, pageCount);
  const visible = users.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4, 16px)' }}>
      <JxTable>
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {visible.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <JxBadge tone={user.active ? 'success' : 'danger'} dot>
                  {user.active ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
        </tbody>
      </JxTable>

      {pageCount > 1 && (
        <JxPagination
          total={pageCount}
          page={currentPage}
          onPageChange={setPage}
          aria-label="Навигация по страницам пользователей"
        />
      )}
    </div>
  );
}

export default UsersTable;

